require 'includes/functions.php'; $id=(int)($_GET['id']??0);$q=db()->prepare('SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=?');$q->execute([$id]);$p=$q->fetch();if(!$p)go('products.php');add_recent($id);
if($_SERVER['REQUEST_METHOD']==='POST'){ require_login();$action=$_POST['action']??''; if($action==='wishlist'){db()->prepare('INSERT IGNORE INTO wishlist(user_id,product_id) VALUES(?,?)')->execute([user()['id'],$id]);flash('success','Added to your wishlist.');go('wishlist.php');} $size=$_POST['size']??'';$qty=max(1,(int)($_POST['qty']??1));$s=db()->prepare('SELECT stock_quantity FROM product_sizes WHERE product_id=? AND size=?');$s->execute([$id,$size]);$stock=(int)$s->fetchColumn();if(!$size||$stock<$qty){flash('danger','Select an available size and quantity.');go('product-details.php?id='.$id);}$_SESSION['cart'][$id]=['size'=>$size,'qty'=>$qty];flash('success','T-shirt added to cart.');go($action==='buy'?'checkout.php':'cart.php'); }
$sizes=db()->prepare('SELECT size,stock_quantity FROM product_sizes WHERE product_id=? ORDER BY FIELD(size,"S","M","L","XL","XXL","XXXL")');$sizes->execute([$id]);$sizes=$sizes->fetchAll();$related=db()->prepare("SELECT * FROM products WHERE status='active' AND id!=? AND (category_id=? OR brand=?) LIMIT 4");$related->execute([$id,$p['category_id'],$p['brand']]);$related=$related->fetchAll();$pageTitle=$p['name'];require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5"><div class="row g-5"><div class="col-md-6"><img class="img-fluid bg-white" src="<?=base(e($p['image']))?>" alt="<?=e($p['name'])?>"></div><div class="col-md-6"><p class="tracking text-muted mb-1"><?=e($p['category_name'])?></p><h1 class="section-title"><?=e($p['name'])?></h1><p class="text-warning">★ <?=$p['rating']?> / 5 <span class="text-muted">(<?=$p['review_count']?> reviews)</span></p><h3><?=money(product_price($p))?> <?php if($p['discount_percent']): ?><span class="price-old fs-6"><?=money($p['original_price'])?></span> <span class="badge badge-lime"><?=$p['discount_percent']?>% OFF</span><?php endif ?></h3><p><?=e($p['description'])?></p><dl class="row"><dt class="col-4">Material</dt><dd class="col-8"><?=e($p['material'])?></dd><dt class="col-4">Fit</dt><dd class="col-8"><?=e($p['fit_type'])?></dd><dt class="col-4">Colour</dt><dd class="col-8"><?=e($p['color'])?></dd></dl><?php if($p['status']!=='active'||$p['stock_quantity']<=0): ?><div class="alert alert-dark">OUT OF STOCK</div><?php else: ?><form method="post" class="needs-size"><p class="fw-bold">Select size</p><div class="d-flex flex-wrap gap-2 mb-3"><?php foreach($sizes as $s): ?><input type="radio" class="btn-check" name="size" value="<?=$s['size']?>" id="size<?=$s['size']?>" <?=$s['stock_quantity']<=0?'disabled':''?>><label class="btn btn-outline-dark <?=$s['stock_quantity']<=0?'disabled':''?>" for="size<?=$s['size']?>"><?=$s['size']?></label><?php endforeach ?></div><div class="mb-3"><label>Quantity</label><input class="form-control" style="max-width:100px" min="1" max="<?=$p['stock_quantity']?>" type="number" name="qty" value="1"></div><div class="d-flex gap-2"><button class="btn btn-dark btn-lg" name="action" value="cart">Add to Cart</button><button class="btn btn-outline-dark btn-lg" name="action" value="buy">Buy Now</button><button class="btn btn-light border btn-lg" name="action" value="wishlist">♡</button></div></form><?php endif ?></div></div><section class="mt-5"><h2 class="section-title">You may also like</h2><div class="row g-3 mt-1"><?php foreach($related as $r): ?><div class="col-6 col-md-3"><div class="card product-card"><img class="product-image" src="<?=base(e($r['image']))?>"><div class="card-body"><h6><?=e($r['name'])?></h6><b><?=money(product_price($r))?></b><br><a href="<?=base('product-details.php?id='.$r['id'])?>" class="btn btn-dark btn-sm mt-2">View Tee</a></div></div></div><?php endforeach ?></div></section></main><?php require 'includes/footer.php'; ?>
